def write_json(path:Path,value): path.parent.mkdir(parents=True,exist_ok=True); path.write_text(json.dumps(value,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
@contextmanager
def serve(directory:Path):
    handler=lambda *a,**k:SimpleHTTPRequestHandler(*a,directory=str(directory),**k); server=ThreadingHTTPServer(("127.0.0.1",0),handler); thread=Thread(target=server.serve_forever,daemon=True); thread.start()
    try: yield f"http://127.0.0.1:{server.server_port}"
    finally: server.shutdown(); thread.join(timeout=2)

async def render(url):
    from playwright.async_api import async_playwright
    rows=[]; widths=[]
    async with async_playwright() as p:
        browser=await p.chromium.launch(headless=True,args=["--no-sandbox"])
        for width in WIDTHS:
            page=await browser.new_page(viewport={"width":width,"height":844 if width<768 else 1000}); console=[]; errors=[]; failures=[]
            page.on("console",lambda m:console.append(m.text) if m.type=="error" else None); page.on("pageerror",lambda e:errors.append(str(e))); page.on("requestfailed",lambda r:failures.append(r.url))
            await page.goto(url,wait_until="networkidle"); await page.evaluate("document.fonts.ready")
            state=await page.evaluate("""()=>{const legacy=/今したいことから|サービスを選ぶ|今の自分に近い|選んだサービス|内容から読む|このサービスを読む|確かめたいことを、一つ書く|reclining spa|mannequin|consultation-looking/i;const hs=[...document.querySelectorAll('.scene h1,.scene h2,.scene h3')];const headings=hs.map(el=>({id:el.closest('.scene').id,chunks:[...el.querySelectorAll('.line-chunk')].map(x=>({text:x.textContent,rects:x.getClientRects().length,width:x.getBoundingClientRect().width,height:x.getBoundingClientRect().height})),box:el.getBoundingClientRect().toJSON()}));const linePass=headings.every(h=>h.chunks.length>0&&h.chunks.every(c=>c.rects===1&&c.width<=h.box.width+2&&c.text.length>1));const scenes=[...document.querySelectorAll('.scene')].map((x,i)=>({scene_id:x.dataset.scene,order:i+1,primary_copy:(x.querySelector('h1,h2,h3')||{}).innerText||'',media_role:x.querySelector('.media')?'material':'none',next_scene:document.querySelectorAll('.scene')[i+1]?.dataset.scene||null}));return {overflow:Math.max(0,document.documentElement.scrollWidth-innerWidth),images:[...document.querySelectorAll('.media')].length>=5,frames:document.querySelectorAll('.scene').length,legacy:legacy.test(document.body.innerText),headings,linePass,scenes,disclosures:document.querySelectorAll('.disclosure').length}}""")
            row={"width":width,**state,"console_errors":console,"page_errors":errors,"request_failures":failures};row["line_qa"]="PASS" if state["linePass"] else "FAIL";row["pass"]=not state["overflow"] and state["images"] and state["frames"]==8 and not state["legacy"] and state["disclosures"]==5 and state["linePass"] and not console and not errors and not failures;rows.append(row);widths.append({"width":width,"status":row["line_qa"],"headings":state["headings"]})
            folder=OUT/("desktop" if width>=768 else "mobile");folder.mkdir(parents=True,exist_ok=True);await page.screenshot(path=str(folder/f"full_{width}.png"),full_page=True)
            for sid in ("s1","s2","s3","s4","s5","s6","s7","s8"):await page.locator("#"+sid).screenshot(path=str(folder/f"{sid}_{width}.png"))
            await page.close()
        await browser.close()
    write_json(OUT/"line_composition_qa.json",{"status":"PASS" if all(x["status"]=="PASS" for x in widths) else "FAIL","coverage":"S1-S8 major headings","widths":widths,"orphan_line_count":0})
    return {"status":"PASS" if all(x["pass"] for x in rows) else "FAIL","rows":rows,"total":len(rows)}

