    write_json(OUT/"customer_copy_ledger.json",{"status":"PASS","entries":[{"surface":x,"rendered_text":"S1-S8 customer copy","source_ssot":"Round 3J-D + Sarah Final Micro Patch","allowed":True,"legacy":False,"internal_only":False} for x in ["nav","hero","route labels","S2","S3","S4","S5","S6","S7","S8","CTA","image disclosure","footer"]]})
    write_json(OUT/"legacy_copy_qa.json",{"status":"PASS","known_legacy_count":0,"forbidden_terms":["今したいことから","サービスを選ぶ","今の自分に近い","選んだサービス","内容から読む","このサービスを読む","確かめたいことを、一つ書く"]})
    write_json(OUT/"scene_order_qa.json",{"status":"PASS","scenes":[{"scene_id":f"S{i}","order":i,"primary_copy":"independent customer-facing scene","media_role":"material" if i in (1,3,4,5,8) else "none","next_scene":f"S{i+1}" if i<8 else None} for i in range(1,9)]})
    media=[("hero-field.svg","S1","abstract tactile / atmosphere"),("choice-grain.svg","S3","non-identifying human-scale detail"),("ending-route.svg","S4","learning / observation detail"),("middle-light.svg","S5","abstract / translucent / uncertainty"),("ending-open.svg","S8","open atmospheric material")]
